body:
Hi! I made some improvements on the GDScript code, that in my opinion make the code cleaner, more readable and maybe a bit more performent. Of course these are just suggestions, and I don't want to be some bad person that bullies you to change your PR, but these changes are good in my opinion.

Here is a quick list of what I changed:
- Added static typing
- Removed unnesecary comments
- Added some comments
- Removed one unnesecary variable (cls in the for loop)
- Restructured some parts so it makes more sense and is more readable

Thanks for reading this.


	## This is the _init function

	# This Array will be printed to stdout, as the result
	var output: Array = []

	var singletons: PackedStringArray = Engine.get_singleton_list()

	# cls_name is chosen instead of class_name, because class_name is a keyword
	var classes: PackedStringArray = ClassDB.get_class_list()
	# Consider removing the following line, because classes is already sorted
	classes.sort()

	for cls_name: String in classes:
		var is_singleton: bool = singletons.has(cls_name)

		var methods: Array[Dictionary] = ClassDB.class_get_method_list(cls_name, false)
		for method: Dictionary in methods:
			# Get the arguments
			var method_args: Array[Dictionary] = []
			for arg: Dictionary in method.get("args", []):
				method_args.push_back({
					"name": String(arg.get("name", "")), # String() is kept for readability
					"type": int(arg.get("type", 0)) # int() is kept for readability
				})

			# Get the return data
			var method_return: Dictionary = method.get("return", {})
			var method_return_type: int = method_return.get("type", 0)

			# Create the entry
			var entry: Dictionary = {
				"class": cls_name,
				"name": String(method.get("name", "")), # String() is kept for readability
				"return_type": int(method_return_type), # int() is kept for readability
				"args": [],
				"static": false,
				"singleton": is_singleton
			}
			output.append(entry)

		# Synthetic static accessor for singleton classes.
		if is_singleton:
			output.append({
				"class": cls_name,
				"name": "get_singleton",
				"return_type": 24, # Object/ObjectID path in your generator
				"args": [],
				"static": true,
				"singleton": true
			})

	print(JSON.stringify(output, "\t"))
	quit()

